import { type EvidenceLog, factSignature } from "./evidence-log.js";

/**
 * Strict pre-submit quality/anti-rejection gate. A candidate that fails any check is
 * dropped from the run, never submitted. The goal is to stay on the Standard tier:
 * no spam, no unverifiable items, no both-sides hedging, no known facts.
 *
 * Item budget (per competition guide: "up to 3 items in total: a note, links and files"):
 * interpreted as 1 (note) + 1 (links block) + up to 1 attached CSV = 3 items.
 * If DELPHI counts each link separately, this bundle still fits the cap.
 */

export const ITEM_BUDGET = 3;
const MIN_EDGE_PCT = 2.5; // evidence must move the implied probability by at least this

export interface GateContext {
  market: CompetitionMarket;
  entry: EntryState;
  log: EvidenceLog;
  /** Online submissions already on the market for this account (live check). */
  onlineSubmissionCount: number;
}

export function gateCandidate(c: EvidenceCandidate, ctx: GateContext): GateVerdict {
  const reasons: string[] = [];
  const warnings: string[] = [];

  if (!ctx.entry.canSubmit) reasons.push("entry state canSubmit=false");
  const slots = ctx.entry.remainingOnMarket - ctx.onlineSubmissionCount - ctx.log.submittedCount(ctx.market.address);
  if (slots <= 0) reasons.push("no submission slots left on market");
  if (ctx.entry.restricted) {
    warnings.push(
      "restricted tier: max 1 submission per market (would not be Standard-tier multi-submit)",
    );
  }
  if (Number(ctx.entry.judgementPotRemainingBaseUnits) <= 0) {
    warnings.push("judgment pot empty: judgment bounty $0 (settlement value may still count)");
  }

  // Both-sides rule: settlement value nets to $0 per person per market.
  const locked = ctx.log.lockedStance(c.marketAddress);
  if (locked !== null && locked !== c.stance) {
    reasons.push(`stance lock: market already covered with ${locked.toUpperCase()} stance; refusing ${c.stance.toUpperCase()} (both-sides nets $0)`);
  }

  // Dedupe: same fact signature already drafted/submitted.
  if (ctx.log.hasSignature(c.factSignature)) {
    reasons.push("duplicate: fact signature already in evidence-log.jsonl");
  }

  // Unverifiable risk: the judge fetches cited URLs with no browser/JS.
  if (c.links.length === 0) reasons.push("no links: judge cannot verify");
  for (const link of c.links) {
    let u: URL;
    try {
      u = new URL(link.url);
    } catch {
      reasons.push(`malformed link: ${link.url}`);
      continue;
    }
    if (u.protocol !== "https:" && u.protocol !== "http:") reasons.push(`non-http link: ${link.url}`);
  }
  if (c.figures.length < 2) {
    reasons.push("fewer than 2 key figures pasted into the note (unverifiable risk)");
  }

  // Anti-rejection: never submit bookmaker odds, stale headlines, opinion.
  const bannedFragments = ["bookmaker", "oddschecker", "betting odds", "prediction, ", "in my opinion"];
  const blob = (c.headline + " " + c.figures.join(" ") + " " + c.sourceDescriptions.join(" ")).toLowerCase();
  for (const b of bannedFragments) {
    if (blob.includes(b)) reasons.push(`banned content: "${b}" (known not to earn)`);
  }

  // Known-fact check: evidence that agrees with the market to within the noise floor earns nothing.
  const edge = Math.abs(c.analysis.evidenceImpliedYes - c.marketImpliedYes) * 100;
  if (edge < MIN_EDGE_PCT) {
    reasons.push(
      `evidence-implied P(yes)=${(c.analysis.evidenceImpliedYes * 100).toFixed(1)}% within ` +
        `${MIN_EDGE_PCT}pp of market implied ${(c.marketImpliedYes * 100).toFixed(1)}% (presumed priced)`,
    );
  }

  // Item budget: note (1) + links block (1) + files (n). One CSV attached keeps us at 3.
  const items = 1 + 1 + 1; // note + links + one CSV
  if (items > ITEM_BUDGET) reasons.push(`item budget exceeded: ${items} > ${ITEM_BUDGET}`);

  // Direction sanity: stance is the direction this evidence pushes the market
  // (up on P(yes) = "yes" stance, down = "no" stance), so it must agree with the
  // sign of the derived-vs-market gap.
  const delta = c.analysis.evidenceImpliedYes - c.marketImpliedYes;
  const derivedStance = delta >= 0 ? "yes" : "no";
  if (derivedStance !== c.stance) {
    reasons.push(
      `stance ${c.stance} disagrees with derived P(yes)=${c.analysis.evidenceImpliedYes.toFixed(3)} ` +
        `vs market ${(c.marketImpliedYes * 100).toFixed(1)}%`,
    );
  }

  return { pass: reasons.length === 0, reasons, warnings };
}

export function signatureFor(c: Omit<EvidenceCandidate, "factSignature">): string {
  return factSignature(c.marketAddress, c.headline, c.figures);
}
import { createHash } from "node:crypto";
import { appendFileSync, existsSync, readFileSync } from "node:fs";
import type { EvidenceLogEntry } from "./types.js";

/**
 * evidence-log.jsonl is the local ledger that enforces two competition rules the API
 * cannot enforce for us:
 *  - dedupe: never research or submit the same fact twice (fact signature match)
 *  - one-directional stance per market: evidence for both sides nets to $0 settlement
 *    value, so once a stance is locked for a market, the opposite stance is refused.
 * Append-only; one JSON object per line.
 */

export class EvidenceLog {
  private entries: EvidenceLogEntry[] = [];

  constructor(readonly path: string) {
    if (existsSync(path)) {
      for (const line of readFileSync(path, "utf-8").split("\n")) {
        const t = line.trim();
        if (!t) continue;
        this.entries.push(JSON.parse(t) as EvidenceLogEntry);
      }
    }
  }

  all(): EvidenceLogEntry[] {
    return [...this.entries];
  }

  forMarket(address: string): EvidenceLogEntry[] {
    return this.entries.filter((e) => e.marketAddress === address);
  }

  /** The stance already taken on a market, if any (drafted or submitted entries only). */
  lockedStance(address: string): "yes" | "no" | null {
    const active = this.forMarket(address).filter((e) => e.status !== "rejected");
    if (active.length === 0) return null;
    return active[0]!.stance;
  }

  hasSignature(signature: string): boolean {
    return this.entries.some((e) => e.factSignature === signature && e.status !== "rejected");
  }

  submittedCount(address: string): number {
    return this.forMarket(address).filter((e) => e.status === "submitted").length;
  }

  draftedCount(address: string): number {
    return this.forMarket(address).filter((e) => e.status === "drafted" || e.status === "submitted").length;
  }

  append(entry: EvidenceLogEntry): void {
    this.entries.push(entry);
    appendFileSync(this.path, JSON.stringify(entry) + "\n", "utf-8");
  }
}

export function factSignature(marketAddress: string, headline: string, figures: string[]): string {
  return sha256(marketAddress + "|" + headline + "|" + figures.join("|"));
}

export function sha256(input: string): string {
  return createHash("sha256").update(input, "utf-8").digest("hex");
}
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { randomUUID } from "node:crypto";
import type { CompetitionMarket, DraftManifest, EvidenceCandidate } from "./types.js";

/**
 * Draft writer. One directory per submission under drafts/:
 *   note.md      — the exact 4-part dated note text that would be submitted
 *   data.csv     — compact machine-readable series backing section 3 (written by mathgen)
 *   manifest.json — links, files, stance, idempotency key, submission state
 * The note is a 4-part dated note per the competition guide: dated fact,
 * sources, method, forecast comparison. All key figures are pasted inline so
 * the judge never needs JS rendering (anti-`unverifiable`).
 */

export interface DraftPaths {
  dir: string;
  note: string;
  csv: string;
  manifest: string;
}

export function draftDirFor(runDate: string, topic: string): DraftPaths {
  const dir = join("drafts", `${runDate}-${topic}`);
  return {
    dir,
    note: join(dir, "note.md"),
    csv: join(dir, "data.csv"),
    manifest: join(dir, "manifest.json"),
  };
}

export function composeNote(c: EvidenceCandidate, market: CompetitionMarket): string {
  const pct = (p: number) => (p < 0.001 ? `<0.1%` : `${(p * 100).toFixed(1)}%`);
  const impliedPct = pct(c.analysis.evidenceImpliedYes);
  const marketPct = `${(c.marketImpliedYes * 100).toFixed(1)}%`;
  const push = c.stance === "yes" ? "up" : "down";
  const lines: string[] = [];
  lines.push(`Evidence note — ${c.asOf.slice(0, 10)} (all times UTC)`);
  lines.push("");
  lines.push(`Market: ${market.question}`);
  lines.push(`Market address: ${market.address} — evidence cutoff ${market.evidenceCutoffAt}`);
  lines.push("");
  lines.push("1) DATED FACT");
  lines.push(c.headline);
  lines.push("");
  lines.push("Key figures, copied from the source content at fetch time (also in data.csv):");
  for (const f of c.figures) lines.push(`- ${f}`);
  lines.push("");
  lines.push("2) SOURCES");
  c.links.forEach((l, i) => {
    lines.push(`- [${i + 1}] ${l.url} — ${c.sourceDescriptions[i] ?? l.label} (${l.lang}, ${l.access})`);
  });
  lines.push(
    "- data.csv (attached) holds the full series/derivation table in machine-readable form; every figure above also appears inline so nothing depends on JS or bot-walled pages.",
  );
  lines.push("");
  lines.push("3) METHOD");
  for (const m of c.analysis.methodLines) lines.push(`- ${m}`);
  lines.push("");
  lines.push("4) FORECAST COMPARISON");
  lines.push(`- Market implied P(yes) at snapshot: ${marketPct}%`);
  lines.push(
    `- This evidence implies P(yes) ≈ ${impliedPct} (confidence: ${c.analysis.confidence}) — it pushes the ${c.stance.toUpperCase()} side ${push}.`,
  );
  lines.push(
    `- Stance: ${c.stance.toUpperCase()} side only. No evidence is submitted for the opposite side of this market.`,
  );
  return lines.join("\n") + "\n";
}

export function writeDraft(
  c: EvidenceCandidate,
  market: CompetitionMarket,
  mode: "mock" | "live",
  runDate: string,
): DraftPaths {
  const paths = draftDirFor(runDate, c.topic);
  mkdirSync(paths.dir, { recursive: true });
  const manifest: DraftManifest = {
    topic: c.topic,
    marketAddress: c.marketAddress,
    marketQuestion: c.marketQuestion,
    generatedAt: new Date().toISOString(),
    mode,
    asOf: c.asOf,
    stance: c.stance,
    links: c.links.map((l) => l.url),
    files: ["data.csv"],
    factSignature: c.factSignature,
    idempotencyKey: randomUUID(),
    submittedAt: null,
    submissionId: null,
  };
  writeFileSync(paths.note, composeNote(c, market), "utf-8");
  writeFileSync(paths.manifest, JSON.stringify(manifest, null, 2), "utf-8");
  return paths;
}
import { readFile } from "node:fs/promises";
import type { AgentConfig } from "./config.js";
import type { DraftManifest } from "./types.js";

/**
 * Live submitter. hard-gated: requires mode=live AND LIVE_SUBMIT=1 env AND the
 * --live-submit flag together (resolveConfig). In this build the pipeline never
 * passes --live-submit, so no real submission can occur; the code path exists
 * so Sekar's QA can review exactly what WOULD be sent.
 */

export class SubmitGuardError extends Error {}

export interface SubmitOutcome {
  submissionId: string;
  status: string;
}

export async function submitDraft(cfg: AgentConfig, draftDir: string): Promise<SubmitOutcome> {
  if (!cfg.liveSubmit) {
    throw new SubmitGuardError(
      "submitDraft refused: liveSubmit is off. Set DELPHI_API_ACCESS_KEY, LIVE_SUBMIT=1 and pass --live-submit.",
    );
  }
  const manifest = JSON.parse(await readFile(`${draftDir}/manifest.json`, "utf-8")) as DraftManifest;
  const note = await readFile(`${draftDir}/note.md`, "utf-8");
  const csv = await readFile(`${draftDir}/data.csv`);
  const sdk = await import("@gensyn-ai/gensyn-delphi-sdk");
  const client = new sdk.EvidenceClient({
    baseUrl: cfg.baseUrl,
    apiKey: cfg.delphiApiKey!,
    agentId: cfg.agentId,
    agentHarness: cfg.agentHarness,
    agentModel: cfg.agentModel,
    extraHeaders: {
      // Note + links + one CSV = 3 items, within the per-submission item limit.
      "X-Delphi-Item-Budget": "note+links+1file",
    },
  });
  const { data } = await client.submitEvidence({
    note,
    links: manifest.links,
    files: [new Blob([csv], { type: "text/csv" })],
    marketAddress: manifest.marketAddress,
    idempotencyKey: manifest.idempotencyKey,
  });
  const { data: settled } = await client.waitForSubmission(data.id, { timeoutMs: 10 * 60_000 });
  return { submissionId: settled.id, status: settled.status };
}
